<?php $p='actions['.$idx.']';?>
<article class="action-editor"><input type="hidden" name="<?=$p?>[id]" value="<?=(int)($a['id']??0)?>"><div class="action-editor-head"><b>Ação</b></div><div class="action-fields"><label><span>Causa</span><textarea class="bh-field bh-textarea" name="<?=$p?>[cause]" rows="2"><?=$h($a['cause']??'')?></textarea></label><label><span>O quê?</span><textarea class="bh-field bh-textarea" name="<?=$p?>[what]" rows="2"><?=$h($a['what_text']??'')?></textarea></label><label><span>Por quê?</span><textarea class="bh-field bh-textarea" name="<?=$p?>[why]" rows="2"><?=$h($a['why_text']??'')?></textarea></label><label><span>Como?</span><textarea class="bh-field bh-textarea" name="<?=$p?>[how]" rows="2"><?=$h($a['how_text']??'')?></textarea></label><label><span>Quem? (texto)</span><input class="bh-field" name="<?=$p?>[who_text]" value="<?=$h($a['who_text']??'')?>"></label><label><span>Usuário responsável</span><select class="bh-field bh-select" name="<?=$p?>[responsible_user_id]"><option value="">Selecione</option><?php foreach($users as$u):?><option value="<?=(int)$u['id']?>" <?=(int)($a['responsible_user_id']??0)===(int)$u['id']?'selected':''?>><?=$h($u['name'])?></option><?php endforeach;?></select></label><label><span>Quando? (texto)</span><input class="bh-field" name="<?=$p?>[when_text]" value="<?=$h($a['when_text']??'')?>"></label><label><span>Prazo</span><input class="bh-field" type="date" name="<?=$p?>[due_date]" value="<?=$h($a['due_date']??'')?>"></label><label><span>Status</span><select class="bh-field bh-select" name="<?=$p?>[status]"><?php foreach(['planned'=>'Planejada','in_progress'=>'Em andamento','completed'=>'Concluída','cancelled'=>'Cancelada']as$v=>$label):?><option value="<?=$v?>" <?=($a['status']??'planned')===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><label><span>Data de conclusão</span><input class="bh-field" type="date" name="<?=$p?>[completion_date]" value="<?=$h($a['completion_date']??'')?>"></label></div></article>
